```python
from griffe.loader import load

package = load("requests")

# Get all public top-level functions
public_functions = []
for name, member in package.members.items():
    if not name.startswith('_') and member.is_function:
        public_functions.append(name)

# Sort and print
for func in sorted(public_functions):
    print(func)
